public class User {
    private final String name;
    public User(String name) {
        this.name = name;
    }
}

public void process(User user) {
    if (user != null) {
        if (user.isActive()) {
            System.out.println("Processing...");
        }
    }
}

Answer:
public void process(User user) {
    if (user == null || !user.isActive()) {
        return;
    }
    System.out.println("Processing...");
}

